#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<char> st;  // 내용 전체를 출력하려고 vector 를 스택으로 사용
    string cmd;
    while (cin >> cmd) {
        if (cmd == "type") {
            char c;
            cin >> c;
            st.push_back(c);
        } else if (cmd == "undo" && !st.empty()) {
            st.pop_back();
        }
        if (st.empty()) cout << "(empty)\n";
        else cout << string(st.begin(), st.end()) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    queue<pair<string, int>> q;
    q.push({"A", 3});
    q.push({"B", 5});
    q.push({"C", 1});
    int t = 0;
    while (!q.empty()) {
        auto [name, left] = q.front();
        q.pop();
        int work = min(2, left);
        t += work;
        if (left - work > 0) q.push({name, left - work});
        else cout << name << " done at " << t << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    deque<int> dq = {1, 2, 3};
    dq.push_front(0);
    dq.push_back(4);
    cout << dq.front() << ' ' << dq.back() << ' ' << dq[2] << '\n';
    dq.pop_front();
    dq.pop_back();
    for (int x : dq) cout << x << ' ';
    cout << '\n';

    stack<int> st;
    for (int x : {10, 20, 30}) st.push(x);
    while (!st.empty()) {
        int x = st.top();  // 먼저 읽고
        st.pop();          // 그다음 뺀다
        cout << x << ' ';
    }
    cout << '\n';
    return 0;
}
